          "source": "netlist",
          "quote": "(net (code \"35\") (name \"Net-(U9-Pad2)\") (node (ref \"J1\") (pin \"1\") (pinfunction \"Pin_1\") (pintype \"passive\")) (node (ref \"U2\") (pin \"2\") (pinfunction \"T-\") (pintype \"passive\")) (node (ref \"U9\") (pin \"2\") (pintype \"input\")))"
        },
