          "source": "netlist",
          "quote": "(net (code \"36\") (name \"Net-(U9-Pad4)\") (node (ref \"U3\") (pin \"8\") (pinfunction \"NC\") (pintype \"passive\")) (node (ref \"U9\") (pin \"4\") (pintype \"output\")))"
        },
        {
          "source": "spec",
          "quote": "Pin 8 (`NC`) is left unconnected on all three parts"
        }
      ],
